package imagesearch

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode"

	"github.com/charmbracelet/x/ansi"

	"github.com/anthnel/devdesk/internal/oci"
)

// hubSearchURL is the v1 search endpoint `docker search` uses; not a public
// Hub contract.
var hubSearchURL = "https://index.docker.io/v1/search"

// HubLimit is the validated cap: one request, one page.
const HubLimit = 50

// hubMaxBody caps what is read from the response.
const hubMaxBody = 1 << 20

// hubComponent is one path component of a repository name: lowercase
// alphanumerics joined by '.', '_', '__' or runs of '-' (OCI distribution spec).
var hubComponent = regexp.MustCompile(`^[a-z0-9]+(?:(?:[._]|__|-+)[a-z0-9]+)*$`)

// HubSearcher searches Docker Hub anonymously: one GET, no credentials, no
// pagination. Whatever Target carries for authentication is ignored.
type HubSearcher struct {
	// Endpoint overrides hubSearchURL when set.
	Endpoint string
	// Client overrides the default client (15 s timeout, no redirects).
	Client *http.Client
}

type hubResponse struct {
	Results []struct {
		Name        string `json:"name"`
		Description string `json:"description"`
		IsOfficial  bool   `json:"is_official"`
		StarCount   *int   `json:"star_count"`
	} `json:"results"`
}

// Search runs one anonymous search. A non-200 answer is an *oci.StatusError.
func (h HubSearcher) Search(ctx context.Context, t Target, q Query) ([]Image, bool, error) {
	limit := q.Limit
	if limit <= 0 || limit > HubLimit {
		limit = HubLimit
	}
	endpoint := h.Endpoint
	if endpoint == "" {
		endpoint = hubSearchURL
	}
	u, err := url.Parse(endpoint)
	if err != nil {
		return nil, false, fmt.Errorf("hub search: %w", err)
	}
	vals := u.Query()
	vals.Set("q", q.Text)
	vals.Set("n", strconv.Itoa(limit))
	u.RawQuery = vals.Encode()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
	if err != nil {
		return nil, false, fmt.Errorf("hub search: %w", err)
	}
	client := h.Client
	if client == nil {
		client = &http.Client{
			Timeout: 15 * time.Second,
			CheckRedirect: func(*http.Request, []*http.Request) error {
				return http.ErrUseLastResponse
			},
		}
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, false, fmt.Errorf("hub search: %w", err)
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil, false, &oci.StatusError{Code: resp.StatusCode, Source: oci.SourceRegistry}
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, hubMaxBody+1))
	if err != nil {
		return nil, false, fmt.Errorf("hub search: %w", err)
	}
	if len(body) > hubMaxBody {
		return nil, false, fmt.Errorf("hub search: response over %d bytes", hubMaxBody)
	}
	var parsed hubResponse
	if err := json.Unmarshal(body, &parsed); err != nil {
		return nil, false, fmt.Errorf("hub search: %w", err)
	}

	prefix := strings.Trim(t.RepoPrefix, "/")
	var out []Image
	for _, r := range parsed.Results {
		repo, ok := hubRepo(r.Name)
		if !ok {
			continue
		}
		if prefix != "" && !strings.HasPrefix(repo, prefix+"/") {
			continue
		}
		img := Image{
			EntryKey:    t.EntryKey,
			Name:        strings.TrimPrefix(repo, "library/"),
			Repo:        repo,
			Description: sanitizeDescription(r.Description),
			Official:    r.IsOfficial,
		}
		if r.StarCount != nil {
			img.Stars, img.HasStars = *r.StarCount, true
		}
		out = append(out, img)
		if len(out) == HubLimit {
			break
		}
	}
	return out, false, nil
}

// hubRepo validates a name Hub returned and returns the final repository path:
// a bare name lives under library/ (D39). The name ends up in a docker
// command, so anything that is not a valid repository name is dropped.
func hubRepo(name string) (string, bool) {
	if name == "" {
		return "", false
	}
	parts := strings.Split(name, "/")
	for _, p := range parts {
		if !hubComponent.MatchString(p) {
			return "", false
		}
	}
	if len(parts) == 1 {
		return "library/" + name, true
	}
	return name, true
}

// sanitizeDescription removes escape sequences and control characters (a
// description is remote, untrusted text), invisible format characters (bidi
// overrides, zero-width, BOM: category Cf) and collapses whitespace.
func sanitizeDescription(s string) string {
	s = ansi.Strip(s)
	s = strings.Map(func(r rune) rune {
		switch {
		case r == '\t' || r == '\n' || r == '\r':
			return ' '
		case unicode.IsControl(r), unicode.Is(unicode.Cf, r):
			return -1
		}
		return r
	}, s)
	return strings.Join(strings.Fields(s), " ")
}
package imagesearch

import (
	"context"
	"fmt"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/testutil/loopback"
)

// verdictOf runs HubSearcher against endpoint and classifies the answer.
func verdictOf(ctx context.Context, endpoint string) (Outcome, error) {
	imgs, partial, err := HubSearcher{Endpoint: endpoint}.Search(ctx, Target{}, Query{Text: "nginx"})
	return Classify(err, len(imgs), partial), err
}

func TestVerdictHTTP(t *testing.T) {
	cases := []struct {
		name   string
		status int
		body   string
		want   Verdict
	}{
		{"404", http.StatusNotFound, "", VerdictRefused},
		{"405", http.StatusMethodNotAllowed, "", VerdictRefused},
		{"401", http.StatusUnauthorized, "", VerdictRefused},
		{"403", http.StatusForbidden, "", VerdictRefused},
		{"429", http.StatusTooManyRequests, "", VerdictFailed},
		{"500", http.StatusInternalServerError, "", VerdictFailed},
		{"invalid body", http.StatusOK, "<html>not json", VerdictFailed},
		{"empty body", http.StatusOK, "", VerdictFailed},
		{"empty response", http.StatusOK, `{"results":[]}`, VerdictNoResult},
		{"results", http.StatusOK, `{"results":[{"name":"nginx","is_official":true}]}`, VerdictOK},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
				w.WriteHeader(tc.status)
				_, _ = w.Write([]byte(tc.body))
			}))
			t.Cleanup(srv.Close)
			got, err := verdictOf(context.Background(), srv.URL)
			if got.Verdict != tc.want {
				t.Errorf("verdict = %v, want %v (err = %v)", got.Verdict, tc.want, err)
			}
			if got.Partial || got.Skipped {
				t.Errorf("marks = %+v, want none", got)
			}
		})
	}
}

func TestVerdictHTTPDeadlineExceeded(t *testing.T) {
	release := make(chan struct{})
	srv := httptest.NewServer(http.HandlerFunc(func(_ http.ResponseWriter, r *http.Request) {
		select {
		case <-r.Context().Done():
		case <-release:
		}
	}))
	t.Cleanup(srv.Close)
	t.Cleanup(func() { close(release) })

	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	got, err := verdictOf(ctx, srv.URL)
	if err == nil {
		t.Fatal("err = nil, want a deadline error")
	}
	if got.Verdict != VerdictFailed {
		t.Errorf("verdict = %v, want %v (err = %v)", got.Verdict, VerdictFailed, err)
	}
}

func TestVerdictHTTPNetworkError(t *testing.T) {
	// The port is held bound but never listening, so connect() is refused
	// deterministically and no bind(0) can be handed it.
	url := fmt.Sprintf("http://127.0.0.1:%d", loopback.ReservePort(t))

	got, err := verdictOf(context.Background(), url)
	if err == nil {
		t.Fatal("err = nil, want a connection error")
	}
	if got.Verdict != VerdictFailed {
		t.Errorf("verdict = %v, want %v (err = %v)", got.Verdict, VerdictFailed, err)
	}
}

