package ociresources

import (
	"cmp"
	"slices"
	"strings"
)

// The ranks of matchTier, lowest first.
const (
	tierExact      = iota // the name is the query
	tierLastEquals        // the last path segment is the query
	tierLastPrefix        // the last path segment starts with the query
	tierContains          // the name contains the query
	tierNoMatch           // nothing in the name matches
)

// matchTier ranks name against query, lowest first, case-insensitive.
func matchTier(query, name string) int {
	q, n := strings.ToLower(query), strings.ToLower(name)
	last := n[strings.LastIndex(n, "/")+1:]
	switch {
	case n == q:
		return tierExact
	case last == q:
		return tierLastEquals
	case strings.HasPrefix(last, q):
		return tierLastPrefix
	case strings.Contains(n, q):
		return tierContains
	}
	return tierNoMatch
}

// sortSearchRows orders rows by matchTier, then lower-cased name, then
// registry alias (label), then EntryKey, then Repo. The result depends only on the rows
// and the query, never on which registry answered first (DEVDESK-302). Stars
// play no part.
func TestClassify(t *testing.T) {
	for _, tc := range classifyCases() {
		t.Run(tc.name, func(t *testing.T) {
			if got := Classify(tc.err, tc.n, tc.partial); got != tc.want {
				t.Errorf("Classify(%v, %d, %v) = %+v, want %+v", tc.err, tc.n, tc.partial, got, tc.want)
			}
		})
	}
}

// One verdict per answer, and a mark only with its own verdict.
func TestClassifyMarksOnlyTheirVerdict(t *testing.T) {
	for _, tc := range classifyCases() {
		t.Run(tc.name, func(t *testing.T) {
			o := Classify(tc.err, tc.n, tc.partial)
			switch o.Verdict {
			case VerdictOK, VerdictNoResult, VerdictRefused, VerdictFailed:
			default:
				t.Fatalf("verdict = %d, want one of the four", o.Verdict)
			}
			if o.Partial && o.Verdict != VerdictOK {
				t.Errorf("Partial set with %v", o.Verdict)
			}
			if o.Skipped && o.Verdict != VerdictNoResult {
				t.Errorf("Skipped set with %v", o.Verdict)
			}
		})
	}
}

func TestVerdictString(t *testing.T) {
	if !errors.Is(err, ErrUnsupported) {
		t.Fatalf("err = %v, want ErrUnsupported", err)
	}
}

// dhi.io has no documented catalog API: refused without any request.
func TestDHIIsRefusedWithoutARequest(t *testing.T) {
	for _, url := range []string{"dhi.io", "https://dhi.io", "https://DHI.io/", "dhi.io:443", "http://dhi.io/library"} {
		t.Run(url, func(t *testing.T) {
			hub, other := &recorder{name: "hub"}, &recorder{name: "other"}
			imgs, partial, err := ByRegistry(hub, other).Search(context.Background(), Target{RegistryURL: url}, Query{Text: "nginx"})
			if !errors.Is(err, ErrUnsupported) {
				t.Fatalf("err = %v, want ErrUnsupported", err)
			}
			if len(imgs) != 0 || partial {
				t.Errorf("images = %v, partial = %v, want nothing", imgs, partial)
			}
			if hub.count() != 0 || other.count() != 0 {
				t.Errorf("hub calls = %d, other calls = %d, want 0 and 0", hub.count(), other.count())
			}
			if v := Classify(err, 0, false).Verdict; v != VerdictRefused {
				t.Errorf("verdict = %v, want refused", v)
			}
		})
	}
}

func TestDHILookalikesAreNotRefused(t *testing.T) {
	for _, url := range []string{"notdhi.io", "registry.dhi.io", "dhi.io.example.com"} {
		t.Run(url, func(t *testing.T) {
			hub, other := &recorder{name: "hub"}, &recorder{name: "other"}
			_, _, err := ByRegistry(hub, other).Search(context.Background(), Target{RegistryURL: url}, Query{Text: "nginx"})
			if err != nil {
				t.Fatalf("err = %v", err)
			}
			if hub.count() != 0 || other.count() != 1 {
				t.Errorf("hub calls = %d, other calls = %d, want 0 and 1", hub.count(), other.count())
			}
		})
	}
}
